function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Sky
  brush.fill("#87CEEB"); // Sky blue
  brush.fillBleed(0.3);
  brush.beginShape();
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.vertex(400, 400);
  brush.vertex(0, 400);
  brush.endShape(true);

  // Clouds
  brush.fill("#E6E6E6"); // Light gray clouds
  brush.fillBleed(0.5);
  brush.beginShape();
  brush.vertex(0, 200);
  brush.vertex(200, 250);
  brush.vertex(400, 200);
  brush.vertex(200, 150);
  brush.endShape(true);

  // Sun
  brush.fill("#FFD700"); // Golden yellow sun
  brush.fillBleed(0.8);
  brush.beginShape();
  brush.vertex(200, 100);
  brush.vertex(220, 80);
  brush.vertex(180, 100);
  brush.vertex(200, 120);
  brush.endShape(true);

  // Green hills
  brush.fill("#336633"); // Dark green hills
  brush.fillBleed(0.2);
  brush.beginShape();
  brush.vertex(0, 250);
  brush.vertex(400, 250);
  brush.vertex(400, 300);
  brush.vertex(0, 300);
  brush.endShape(true);

  // Trees
  brush.fill("#8B4513"); // Olive trees
  brush.fillBleed(0.5);
  brush.beginShape();
  brush.vertex(100, 320);
  brush.vertex(120, 350);
  brush.vertex(140, 330);
  brush.vertex(160, 300);
  brush.vertex(180, 320);
  brush.endShape(true);

  // Optional: Add more details if needed
}
```

